    "app/pages/index.vue": "<script setup lang=\"ts\">\nconst { data } = await useFetch(\"/api/hello\");\n</script>\n\n<template>\n  <main data-eb-id=\"hero\" class=\"min-h-screen grid place-items-center bg-zinc-50 p-8\">\n    <div class=\"text-center\">\n      <h1 data-eb-id=\"hero-title\" class=\"text-4xl font-bold\">{{ data?.message }}</h1>\n      <p data-eb-id=\"hero-sub\" class=\"mt-2 text-zinc-500\">Renderizado en el servidor a las {{ data?.at }}</p>\n    </div>\n  </main>\n</template>\n",
    "nuxt.config.ts": "import tailwindcss from \"@tailwindcss/vite\";\n\nexport default defineNuxtConfig({\n  compatibilityDate: \"2026-10-01\",\n  css: [\"~/assets/main.css\"],\n  vite: { plugins: [tailwindcss()] },\n  app: {\n    head: {\n      title: \"Mi app\",\n      htmlAttrs: { lang: \"es\" },\n      // Selector de elementos del editor de EasyBits: sólo dentro de su vista previa.\n      script: [{ innerHTML: `if(location.search.includes(\"eb_edit=1\")&&window.top!==window){var s=document.createElement(\"script\");s.src=\"https://www.easybits.cloud/eb-picker.js\";document.body.appendChild(s)}`, tagPosition: \"bodyClose\" }],\n    },\n  },\n});\n",
    "package.json": "{\n  \"name\": \"app\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"nuxt dev --port 3000 --host\",\n    \"build\": \"nuxt build\",\n    \"start\": \"node .output/server/index.mjs\",\n    \"postinstall\": \"nuxt prepare\"\n  },\n  \"dependencies\": {\n    \"@tailwindcss/vite\": \"4.3.3\",\n    \"nuxt\": \"4.6.1\",\n    \"tailwindcss\": \"4.3.3\"\n  }\n}\n",
