    "src/app.css": "@import \"tailwindcss\";\n",
    "src/app.html": "<!doctype html>\n<html lang=\"es\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    %sveltekit.head%\n  </head>\n  <body data-sveltekit-preload-data=\"hover\">\n    <div style=\"display: contents\">%sveltekit.body%</div>\n    <!-- Selector de elementos del editor de EasyBits: sólo dentro de su vista previa. -->\n    <script>if(location.search.includes(\"eb_edit=1\")&&window.top!==window){var s=document.createElement(\"script\");s.src=\"https://www.easybits.cloud/eb-picker.js\";document.body.appendChild(s)}</script>\n  </body>\n</html>\n",
    "src/routes/+layout.svelte": "<script lang=\"ts\">\n  import \"../app.css\";\n  let { children } = $props();\n</script>\n\n<svelte:head><title>Mi app</title></svelte:head>\n{@render children()}\n",
    "src/routes/+page.server.ts": "// Corre sólo en el servidor: base de datos, secretos y APIs van aquí.\nexport const load = async () => ({ message: \"Tu app ya está viva\", at: new Date().toISOString() });\n",
    "src/routes/+page.svelte": "<script lang=\"ts\">\n  let { data } = $props();\n</script>\n\n<main data-eb-id=\"hero\" class=\"min-h-screen grid place-items-center bg-zinc-50 p-8\">\n  <div class=\"text-center\">\n    <h1 data-eb-id=\"hero-title\" class=\"text-4xl font-bold\">{data.message}</h1>\n    <p data-eb-id=\"hero-sub\" class=\"mt-2 text-zinc-500\">Renderizado en el servidor a las {data.at}</p>\n  </div>\n</main>\n",
