    "astro.config.mjs": "import { defineConfig } from \"astro/config\";\nimport node from \"@astrojs/node\";\nimport tailwindcss from \"@tailwindcss/vite\";\n\n// output \"server\" + adaptador Node: páginas con datos en vivo y endpoints en src/pages/api.\n// Una página estática lleva `export const prerender = true`.\nexport default defineConfig({\n  output: \"server\",\n  adapter: node({ mode: \"standalone\" }),\n  vite: { plugins: [tailwindcss()] },\n});\n",
    "package.json": "{\n  \"name\": \"app\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"astro dev --port 3000 --host\",\n    \"build\": \"astro build\",\n    \"start\": \"HOST=0.0.0.0 node ./dist/server/entry.mjs\"\n  },\n  \"dependencies\": {\n    \"@astrojs/node\": \"11.1.7\",\n    \"@tailwindcss/vite\": \"4.3.3\",\n    \"astro\": \"7.3.8\",\n    \"tailwindcss\": \"4.3.3\"\n  }\n}\n",
    "src/layouts/Layout.astro": "---\nimport \"../styles/global.css\";\nconst { title = \"Mi app\" } = Astro.props;\n---\n<html lang=\"es\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>{title}</title>\n  </head>\n  <body>\n    <slot />\n    <!-- Selector de elementos del editor de EasyBits: sólo dentro de su vista previa. -->\n    <script is:inline>if(location.search.includes(\"eb_edit=1\")&&window.top!==window){var s=document.createElement(\"script\");s.src=\"https://www.easybits.cloud/eb-picker.js\";document.body.appendChild(s)}</script>\n  </body>\n</html>\n",
    "src/pages/index.astro": "---\nimport Layout from \"../layouts/Layout.astro\";\n// El frontmatter corre en el servidor en cada visita (output: \"server\").\nconst at = new Date().toISOString();\n---\n<Layout>\n  <main data-eb-id=\"hero\" class=\"min-h-screen grid place-items-center bg-zinc-50 p-8\">\n    <div class=\"text-center\">\n      <h1 data-eb-id=\"hero-title\" class=\"text-4xl font-bold\">Tu app ya está viva</h1>\n      <p data-eb-id=\"hero-sub\" class=\"mt-2 text-zinc-500\">Renderizado en el servidor a las {at}</p>\n    </div>\n  </main>\n</Layout>\n",
